parameters.jsCode:
const response = $input.first().json;
if (response.errors?.length || !response.data?.products || !Array.isArray(response.data.products.edges)) {
  throw new Error('Shopify returned an error or incomplete response; inventory status unknown.');
}
if (response.data.products.pageInfo?.hasNextPage) throw new Error('More than 250 products; pagination required before delivery.');
const products = response.data.products.edges;
const threshold = 10;
const lowStockItems = [];

for (const productEdge of products) {
  const product = productEdge.node;
  if (!Array.isArray(product.variants?.edges) || product.variants.pageInfo?.hasNextPage) throw new Error('Variant data incomplete or paginated; inventory status unknown.');
  const supplier = (product.metafield && product.metafield.value) || 'Unknown supplier';
  const variantEdges = (product.variants && product.variants.edges) || [];
  for (const variantEdge of variantEdges) {
    const variant = variantEdge.node;
    const qty = variant.inventoryQuantity;
    if (typeof qty !== 'number' || !Number.isFinite(qty)) throw new Error('Missing inventory quantity; inventory status unknown.');
    if (typeof qty === 'number' && qty < threshold) {
      lowStockItems.push({
        supplier,
        product: product.title,
        variant: variant.title,
        sku: variant.sku || 'N/A',
        quantity: qty,
      });
    }
  }
}

return [{ json: { lowStockItems } }];

const items = $json.lowStockItems;
const bySupplier = Object.create(null);

for (const item of items) {
  if (!bySupplier[item.supplier]) bySupplier[item.supplier] = [];
  bySupplier[item.supplier].push(item);
}

const output = [];
for (const supplier of Object.keys(bySupplier)) {
  const variants = bySupplier[supplier];
  const itemsText = variants
    .map((v) => `- ${v.product} (${v.variant}), SKU ${v.sku}: ${v.quantity} left`)
    .join('\n');
  output.push({
    json: {
      supplier,
      variants,
      itemsText,
    },
  });
}

return output;

