const original = $('Group low-stock items by supplier').item.json;
let draft;

if ($json.error) {
  draft = 'Could not generate a draft automatically. Please write a reorder email manually using the items listed above.';
} else {
  const content = $json.content;
  draft = (content && content[0] && content[0].text) ? content[0].text.trim() : 'No draft returned.';
}

return {
  json: {
    supplier: original.supplier,
    itemsText: original.itemsText,
    draft,
  },
};

const reports = $json.supplierReports || [];
const today = new Date().toISOString().slice(0, 10);

const sections = reports.map((report) => {
  const lines = [
    `*Supplier: ${report.supplier}*`,
    report.itemsText,
    '_Suggested reorder email (copy-paste and edit as needed):_',
    '```',
    report.draft,
    '```',
  ];
  return lines.join('\n');
});

const text = `*Low stock report — ${today}*\n\n` + sections.join('\n\n');

return [{ json: { text } }];
